var e=[{id:1,text:"¿Qué estructura cerebral, responsable de la toma de decisiones y el control emocional, experimenta un desarrollo significativo durante la adolescencia?",sorted:!1,options:[{text:"La corteza prefrontal",correct:!0},{text:"El hipocampo",correct:!1},{text:"La amígdala",correct:!1},{text:"El cerebelo",correct:!1}]},{id:2,text:"Según Markus (1984) y Luna (2013), ¿cuál es la distinción técnica entre autoconcepto y autoestima?",sorted:!1,options:[{text:"El autoconcepto es una descripción de representaciones, mientras que la autoestima es el juicio valorativo de esas dimensiones.",correct:!0},{text:"La autoestima es innata, mientras que el autoconcepto se construye exclusivamente a través de la interacción social.",correct:!1},{text:"El autoconcepto es global, mientras que la autoestima se divide en dimensiones académica, social y familiar.",correct:!1},{text:"La autoestima precede cronológicamente al desarrollo del autoconcepto en la infancia temprana.",correct:!1}]},{id:3,text:"En el modelo de James Marcia, ¿qué estado de identidad describe a un adolescente que ha adoptado compromisos sin haber pasado por un periodo de crisis o búsqueda personal?",sorted:!1,options:[{text:"Exclusión de la identidad",correct:!0},{text:"Moratoria",correct:!1},{text:"Logro de identidad",correct:!1},{text:"Difusión de identidad",correct:!1}]},{id:4,text:"De acuerdo con las investigaciones sobre la evolución de la autoestima, ¿qué tendencia se observa habitualmente durante la adolescencia?",sorted:!1,options:[{text:"Disminuye en la adolescencia temprana y tiende a aumentar en las fases intermedia y tardía.",correct:!0},{text:"Se mantiene linealmente estable si el autoconcepto académico es positivo.",correct:!1},{text:"Aumenta drásticamente al inicio de la pubertad debido al sentimiento de madurez.",correct:!1},{text:"Es consistentemente más alta en las chicas debido a su maduración precoz.",correct:!1}]},{id:5,text:"¿Cuál es la principal diferencia entre la percepción de la maduración precoz en chicos y chicas?",sorted:!1,options:[{text:"Los chicos suelen recibirla mejor por la ganancia en superioridad física, mientras que en las chicas es más complejo y a veces se intenta ocultar.",correct:!0},{text:"Las chicas la prefieren porque les permite integrarse antes en el grupo de iguales adultos.",correct:!1},{text:"Los chicos se sienten amenazados por el aumento de masa muscular debido a la presión social.",correct:!1},{text:"No existen diferencias significativas; ambos géneros sufren el mismo nivel de insatisfacción corporal.",correct:!1}]},{id:6,text:"¿Qué concepto introducido por Steinberg (1986) evalúa la desvinculación afectiva de los padres y la percepción de estos como individuos con necesidades propias?",sorted:!1,options:[{text:"Autonomía emocional",correct:!0},{text:"Apego inseguro-evitativo",correct:!1},{text:"Moratoria psicosocial",correct:!1},{text:"Emancipación cognitiva",correct:!1}]},{id:7,text:'En relación con los estilos parentales, ¿cómo se define el estilo "indiferente o negligente" y qué impacto tiene en el adolescente?',sorted:!1,options:[{text:"Se caracteriza por la ausencia de normas y afecto, provocando inseguridad y bajo rendimiento escolar.",correct:!0},{text:"Es aquel donde los padres son receptivos pero poco exigentes, generando una autoestima artificialmente alta.",correct:!1},{text:"Consiste en ejercer un control rígido sin comunicación, derivando en rebeldía y miedo.",correct:!1},{text:"Se basa en el diálogo y la negociación flexible, fomentando la responsabilidad.",correct:!1}]},{id:8,text:'¿Qué papel juega el "conflicto cotidiano" en el entorno familiar durante la adolescencia?',sorted:!1,options:[{text:"Ayuda a la construcción de la autonomía personal, a pesar de generar incertidumbre en los padres.",correct:!0},{text:"Es un indicador patológico que predice el fracaso en la adquisición de la identidad.",correct:!1},{text:"Debe evitarse mediante la sumisión de los hijos para garantizar un desarrollo emocional estable.",correct:!1},{text:"Determina que el adolescente siempre tome decisiones opuestas al criterio de sus padres en temas importantes.",correct:!1}]},{id:9,text:"En el desarrollo moral de Piaget, ¿cuál es el hito que marca la transición de la moralidad heterónoma a la autónoma?",sorted:!1,options:[{text:"El paso de la obediencia ciega a la autoridad hacia un sistema basado en el respeto mutuo y la reciprocidad.",correct:!0},{text:"La capacidad de evitar el castigo mediante el intercambio de favores.",correct:!1},{text:"La interiorización total de las normas impuestas por los padres antes de los 5 años.",correct:!1},{text:"El desarrollo de la capacidad de pensamiento concreto.",correct:!1}]},{id:10,text:"En el Nivel I (Preconvencional) de Kohlberg, ¿qué define la moralidad en el Estadio 1?",sorted:!1,options:[{text:"El egocentrismo y el miedo al castigo impuesto por una autoridad externa.",correct:!0},{text:"La búsqueda del beneficio mutuo y la devolución de favores.",correct:!1},{text:'El deseo de agradar a los demás y ser visto como un "buen chico".',correct:!1},{text:"La adhesión a los derechos humanos universales.",correct:!1}]},{id:11,text:'¿Por qué Kohlberg denomina a su enfoque como "cognitivo-evolutivo"?',sorted:!1,options:[{text:"Porque considera que el desarrollo moral depende de la transformación de estructuras mentales a través de la interacción con el medio.",correct:!0},{text:"Porque se centra exclusivamente en el aprendizaje memorístico de los códigos legales.",correct:!1},{text:"Porque asume que la moralidad es un instinto biológico que evoluciona sin influencia ambiental.",correct:!1},{text:"Porque separa estrictamente el desarrollo afectivo del desarrollo de la inteligencia.",correct:!1}]},{id:12,text:"Según el Estadio 3 de Kohlberg, propio de la adolescencia temprana, ¿cuál es la principal motivación para actuar moralmente?",sorted:!1,options:[{text:"Agradar a los demás y cumplir con las expectativas del grupo para ser aceptado.",correct:!0},{text:"Garantizar que el sistema social no colapse manteniendo la ley y el orden.",correct:!1},{text:"Maximizar el beneficio personal mediante el intercambio instrumental.",correct:!1},{text:"Defender los derechos individuales por encima de las leyes injustas.",correct:!1}]},{id:13,text:'¿Cuál es la consecuencia pedagógica de una autoestima "desajustada" en el alumno?',sorted:!1,options:[{text:"Tendencia a echar la culpa a otros de sus debilidades y escasa tolerancia a la frustración.",correct:!0},{text:"Capacidad para afrontar retos con entusiasmo aunque el resultado sea incierto.",correct:!1},{text:"Independencia total del juicio de los profesores y compañeros.",correct:!1},{text:"Aumento de la creatividad debido a la necesidad de destacar.",correct:!1}]},{id:14,text:"Respecto a la amistad en la adolescencia, ¿qué factor permite que las relaciones pasen de ser meramente lúdicas a ser íntimas y prosociales?",sorted:!1,options:[{text:"La maduración cognitiva y el tiempo dedicado a hablar de sí mismos.",correct:!0},{text:"La disminución del pensamiento formal mencionado por Piaget.",correct:!1},{text:"La necesidad de sustituir el afecto de los padres por el de una pareja romántica.",correct:!1},{text:"El alejamiento de cualquier norma o valor moral autónomo.",correct:!1}]},{id:15,text:"¿Cuál de estas afirmaciones sobre la sexualidad adolescente se menciona en el texto de Garaigordobil (2006)?",sorted:!1,options:[{text:"La emergencia de la sexualidad despierta temores sobre la identidad sexual y miedos frente al otro sexo.",correct:!0},{text:"El deseo de contacto sexual desaparece debido a la concentración en el autoconcepto académico.",correct:!1},{text:"Los adolescentes tienen una seguridad plena en su identidad sexual desde el inicio de la pubertad.",correct:!1},{text:"El enamoramiento carece de intensidad y se vive de forma meramente racional.",correct:!1}]},{id:16,text:'¿Qué implica el sentimiento de "integridad personal" dentro del desarrollo de la identidad?',sorted:!1,options:[{text:"Que las acciones y decisiones sean coherentes entre sí y conformen un estilo propio estable.",correct:!0},{text:"Que el adolescente ignore totalmente las normas de los grupos en los que se integra.",correct:!1},{text:"La capacidad de cambiar de personalidad radicalmente según el contexto social para agradar.",correct:!1},{text:"El rechazo a cualquier experiencia del pasado para centrarse solo en el presente.",correct:!1}]},{id:17,text:"En el contexto de la familia democrática, ¿cómo ejercen los padres el control sobre sus hijos adolescentes?",sorted:!1,options:[{text:"De forma moderada y flexible, cediendo autonomía a medida que el hijo demuestra responsabilidad.",correct:!0},{text:"Mediante una vigilancia absoluta y reglas innegociables para evitar cualquier riesgo.",correct:!1},{text:"Evitando cualquier tipo de control para no entrar en conflicto con el adolescente.",correct:!1},{text:"Delegando la responsabilidad del control en los profesores y el centro educativo.",correct:!1}]},{id:18,text:"¿Qué crítica plantean Ryan y Lynch (1989) a la idea de que la desvinculación afectiva de los padres es necesaria?",sorted:!1,options:[{text:"Que una alta autonomía emocional puede reflejar una falta previa de apoyo y un apego inseguro-evitativo.",correct:!0},{text:"Que la autonomía emocional solo es posible si el adolescente vive fuera del hogar familiar.",correct:!1},{text:"Que los padres deben ser desidealizados para que el adolescente no sufra de narcisismo.",correct:!1},{text:"Que el conflicto con los padres es puramente biológico y no tiene relación con el apego.",correct:!1}]},{id:19,text:'¿Cuál es el riesgo de que el adolescente se encuentre en un estado de "moratoria" prolongado?',sorted:!1,options:[{text:"No se menciona un riesgo negativo intrínseco, sino que representa un momento crucial y necesario de búsqueda.",correct:!0},{text:"Que el adolescente caiga inevitablemente en la delincuencia por falta de compromiso.",correct:!1},{text:"La pérdida irreversible de la capacidad de pensamiento abstracto.",correct:!1},{text:"El desarrollo de una autoestima exageradamente alta por falta de críticas.",correct:!1}]},{id:20,text:"Un alumno que cambia de opinión y comportamiento con frecuencia según el grupo en el que esté, está demostrando:",sorted:!1,options:[{text:"Una autoestima desajustada por ser fácilmente influenciable.",correct:!0},{text:"Una identidad de logro por su gran flexibilidad social.",correct:!1},{text:"Un estadio moral postconvencional basado en el contrato social.",correct:!1},{text:"Una alta autonomía emocional respecto a su familia.",correct:!1}]},{id:21,text:"¿Qué factor se considera decisivo para que la autoestima global sea elevada, independientemente de tener fallos en algunas esferas?",sorted:!1,options:[{text:"La importancia que el propio adolescente otorgue a cada área específica.",correct:!0},{text:"Tener un rendimiento académico sobresaliente en todas las materias.",correct:!1},{text:"La aprobación incondicional de los padres independientemente de la conducta.",correct:!1},{text:"Evitar cualquier tipo de comparación con el grupo de iguales.",correct:!1}]},{id:22,text:"Según el modelo de Kohlberg, ¿en qué fase de la vida se suele realizar la transición del nivel convencional al postconvencional?",sorted:!1,options:[{text:"Durante la adolescencia.",correct:!0},{text:"En la infancia temprana (antes de los 7 años).",correct:!1},{text:"Únicamente al llegar a la vejez tras la jubilación.",correct:!1},{text:"Nunca, ya que el nivel postconvencional es puramente teórico.",correct:!1}]},{id:23,text:"En las familias autoritarias, ¿qué tipo de equilibrio emocional suelen presentar los adolescentes?",sorted:!1,options:[{text:"Poco equilibrados emocionalmente, con falta de autonomía y seguridad.",correct:!0},{text:"Altamente equilibrados gracias a la claridad de las normas parentales.",correct:!1},{text:"Muy independientes, ya que la rigidez les obliga a buscarse la vida fuera.",correct:!1},{text:"Presentan una autoestima positiva pero son rebeldes ante el profesorado.",correct:!1}]},{id:24,text:"De acuerdo con Muñoz (2000), ¿cómo debe ser la información sobre los cambios de la pubertad para facilitar una actitud positiva?",sorted:!1,options:[{text:"Veraz, clara y concreta, enfatizando la flexibilidad de los momentos de aparición.",correct:!0},{text:"Basada únicamente en comparaciones con los promedios estadísticos de crecimiento.",correct:!1},{text:"Evitada hasta que el adolescente pregunte por iniciativa propia.",correct:!1},{text:"Centrada exclusivamente en los riesgos y enfermedades para prevenir conductas de riesgo.",correct:!1}]},{id:25,text:"¿Cuál es un rasgo notable del desarrollo del razonamiento moral según Berk?",sorted:!1,options:[{text:"Que el desarrollo es muy lento y gradual, y pocas personas llegan al Estadio 5.",correct:!0},{text:"Que se produce un salto brusco del Estadio 1 al 4 durante la pubertad.",correct:!1},{text:"Que el Estadio 3 desaparece por completo al iniciar la etapa adulta.",correct:!1},{text:"Que el razonamiento moral es independiente de la edad cronológica.",correct:!1}]},{id:26,text:'En el contexto de la autoestima, ¿qué significa que un adolescente sea "crítico consigo mismo" según Harter (2011)?',sorted:!1,options:[{text:"Que es más capaz de cuestionarse diferentes aspectos sobre sí mismo, lo que genera inestabilidad.",correct:!0},{text:"Que rechaza cualquier crítica constructiva que provenga de los adultos.",correct:!1},{text:"Que ha alcanzado un nivel de madurez tal que ya no comete errores.",correct:!1},{text:"Que su autoestima es tan baja que odia cualquier aspecto de su personalidad.",correct:!1}]}],a=[{id:1,text:"¿Cuál es el núcleo de la perspectiva interaccionista en el modelo de enseñanza inclusiva?",sorted:!1,options:[{text:"La consideración de que las dificultades de aprendizaje residen exclusivamente en la genética del individuo.",correct:!1},{text:"La interrelación entre las características individuales del alumno y las variables del contexto de enseñanza.",correct:!0},{text:"La priorización del currículo estandarizado sobre las necesidades específicas del alumnado diverso.",correct:!1},{text:"El enfoque en la segregación de alumnos con dificultades para optimizar los recursos del aula ordinaria.",correct:!1}]},{id:2,text:'En el contexto de la LOMLOE, ¿qué diferencia fundamental establece el texto entre contextos "discapacitantes" e "invalidantes"?',sorted:!1,options:[{text:"Que la discapacidad es una condición inamovible que el sistema educativo debe compensar con becas.",correct:!1},{text:"Que las personas son diversas por naturaleza y es el contexto el que debe ser inclusivo para no invalidar dichas diferencias.",correct:!0},{text:"Que el bajo rendimiento es siempre consecuencia de un contexto familiar desestructurado.",correct:!1},{text:"Que la equidad educativa consiste en dar exactamente lo mismo a todos los alumnos independientemente de su punto de partida.",correct:!1}]},{id:3,text:"Desde un punto de vista neurobiológico, ¿qué región cerebral se asocia con la sintomatología del TDAH por su falta de maduración?",sorted:!1,options:[{text:"El lóbulo occipital.",correct:!1},{text:"El cerebelo.",correct:!1},{text:"El córtex prefrontal.",correct:!0},{text:"El hipocampo.",correct:!1}]},{id:4,text:"Un profesor observa que un alumno con TDAH se distrae constantemente al estar cerca de la ventana pero es muy activo físicamente. Según las recomendaciones del texto, ¿cuál sería la ubicación óptima?",sorted:!1,options:[{text:"En la primera fila, justo frente a la mesa del profesor.",correct:!1},{text:"En el fondo del aula o cerca del pasillo.",correct:!0},{text:"En un rincón aislado de la clase para evitar cualquier estímulo social.",correct:!1},{text:"Al lado de los alumnos con mejor rendimiento para que le sirvan de modelo.",correct:!1}]},{id:5,text:"Respecto al Trastorno del Espectro Autista (TEA), ¿cómo se define actualmente la distinción de grados en el DSM-V?",sorted:!1,options:[{text:"A través de la distinción clara entre Autismo de Kanner y Síndrome de Asperger.",correct:!1},{text:"Mediante el nivel de gravedad basado en la necesidad de apoyo externo (I al III).",correct:!0},{text:"Dependiendo exclusivamente de la puntuación obtenida en una prueba de Cociente Intelectual.",correct:!1},{text:"Basándose en la edad en la que se manifiestan los primeros síntomas comunicativos.",correct:!1}]},{id:6,text:"¿Cuál es una conducta característica de los patrones restrictivos y repetitivos en un adolescente con TEA?",sorted:!1,options:[{text:"La búsqueda constante de nuevas experiencias y cambios en la rutina diaria.",correct:!1},{text:"La manifestación de una empatía excesiva que dificulta el juicio social.",correct:!1},{text:"La insistencia en la monotonía y la presencia de intereses muy marcados sobre temas específicos.",correct:!0},{text:"La habilidad para interpretar fluidamente el lenguaje figurado y los sarcasmos.",correct:!1}]},{id:7,text:"Sobre la dislexia, es un trastorno de origen:",sorted:!1,options:[{text:"Psicológico, derivado de un trauma temprano en el aprendizaje de la lectura.",correct:!1},{text:"Intelectual, limitado a alumnos con un CI inferior a la media.",correct:!1},{text:"Neuropsicológico, que afecta al procesamiento de los sonidos y las letras.",correct:!0},{text:"Visual, causado por un defecto en la musculatura ocular que impide el enfoque.",correct:!1}]},{id:8,text:"¿Qué diferencia a la dislexia del desarrollo de la dislexia adquirida?",sorted:!1,options:[{text:"La del desarrollo ocurre tras un accidente cerebral en la edad adulta.",correct:!1},{text:"La adquirida se manifiesta cuando el sujeto ya había aprendido a leer y escribir antes de sufrir un daño cerebral.",correct:!0},{text:"La del desarrollo es temporal, mientras que la adquirida es permanente.",correct:!1},{text:"No existe diferencia clínica, son términos sinónimos en pedagogía.",correct:!1}]},{id:9,text:'¿A qué se refiere el término "depresión externalizante" común en adolescentes?',sorted:!1,options:[{text:"A un estado de apatía extrema y aislamiento total en el hogar.",correct:!1},{text:"A la manifestación del malestar a través de la irritabilidad, malhumor o ira.",correct:!0},{text:"Al aumento del apetito y las horas de sueño como mecanismo de escape.",correct:!1},{text:"A la expresión verbal clara y madura de los sentimientos de tristeza ante el profesorado.",correct:!1}]},{id:10,text:"En el tratamiento de la ansiedad en el aula, ¿cuál de estas acciones es fundamental para el profesor?",sorted:!1,options:[{text:"Ignorar los síntomas para no reforzar la conducta ansiosa del alumno.",correct:!1},{text:'Exponer al alumno a situaciones de alto estrés de forma sorpresiva para que se "acostumbre".',correct:!1},{text:"Validar sus emociones y ofrecer herramientas de regulación y espacios de calma.",correct:!0},{text:"Eliminar todas las evaluaciones y exámenes para que el alumno no sienta presión.",correct:!1}]},{id:11,text:"¿Cómo afecta el perfeccionismo disfuncional al rendimiento energético del estudiante?",sorted:!1,options:[{text:"Aumenta la energía disponible debido a la alta motivación por el éxito.",correct:!1},{text:"Reduce los niveles de energía debido a la preocupación constante por el temor al fracaso.",correct:!0},{text:"No tiene impacto en la energía, solo en la calidad técnica de los trabajos.",correct:!1},{text:"Optimiza el tiempo de estudio al focalizarse solo en lo que es perfecto.",correct:!1}]},{id:12,text:"Respecto a los Trastornos de la Conducta Alimentaria (TCA), ¿qué factor psicológico se destaca como motor de estas patologías más allá de la imagen corporal?",sorted:!1,options:[{text:"La falta de conocimientos sobre nutrición básica en el currículo de ciencias.",correct:!1},{text:"El hambre emocional y las dificultades en la vinculación familiar o social.",correct:!0},{text:"La influencia genética exclusiva que determina el peso corporal desde el nacimiento.",correct:!1},{text:"El exceso de actividad física en las asignaturas de educación deportiva.",correct:!1}]},{id:13,text:"Ante una conducta disruptiva de gravedad menor, como hablar sin permiso, ¿qué técnica de intervención inmediata?",sorted:!1,options:[{text:"Imponer un castigo severo delante de toda la clase para dar ejemplo.",correct:!1},{text:"Emplear señales no verbales o acercarse físicamente al alumno.",correct:!0},{text:"Expulsar al alumno inmediatamente al pasillo para que reflexione.",correct:!1},{text:"Ignorar la conducta sistemáticamente para que se extinga por sí sola.",correct:!1}]},{id:14,text:"¿Por qué se recomienda posponer la conversación con un alumno tras una conducta agresiva o una pelea?",sorted:!1,options:[{text:"Porque el profesor necesita tiempo para redactar el informe de expulsión oficial.",correct:!1},{text:"Porque en ese momento el adolescente no tiene capacidad de escucha ni reflexión objetiva.",correct:!0},{text:"Para que el alumno se sienta ignorado y aumente su sentimiento de culpa.",correct:!1},{text:"Para evitar que el resto de alumnos vean la vulnerabilidad del profesor.",correct:!1}]},{id:15,text:"En relación al alumnado con bajo rendimiento, ¿qué estrategia utilizan algunos para proteger su autoestima ante el posible fracaso?",sorted:!1,options:[{text:"Estudiar más horas que el resto para asegurar el aprobado.",correct:!1},{text:"Establecer metas inalcanzables para culpar a la dificultad de la tarea en lugar de a su capacidad.",correct:!0},{text:"Pedir ayuda constante al profesor para demostrar interés.",correct:!1},{text:"Aumentar su participación en clase para compensar los malos exámenes.",correct:!1}]},{id:16,text:"La procrastinación en adolescentes con bajo rendimiento a menudo se asocia con:",sorted:!1,options:[{text:"Un exceso de tiempo libre y falta de actividades extraescolares.",correct:!1},{text:"Creencias negativas sobre uno mismo y miedo a sacar una nota baja.",correct:!0},{text:"Una capacidad intelectual superior que les permite hacer todo en el último momento.",correct:!1},{text:"La falta de recursos tecnológicos en el hogar para realizar las tareas.",correct:!1}]},{id:17,text:"Según el modelo de Renzulli para las Altas Capacidades, ¿qué tres factores deben interactuar?",sorted:!1,options:[{text:"Memoria prodigiosa, obediencia y alta velocidad de procesamiento.",correct:!1},{text:"Capacidad intelectual superior, compromiso con la tarea y creatividad.",correct:!0},{text:"Liderazgo social, altas notas en todas las materias y ausencia de errores.",correct:!1},{text:"Herencia genética, entorno socioeconómico alto y apoyo pedagógico privado.",correct:!1}]},{id:18,text:'¿A qué se refiere el concepto de "disincronía" en el alumnado con Altas Capacidades?',sorted:!1,options:[{text:"A la falta de coordinación motora fina para escribir correctamente.",correct:!1},{text:"A la diferencia de ritmo madurativo entre la faceta intelectual y la afectiva o social.",correct:!0},{text:"A la incapacidad de realizar dos tareas cognitivas al mismo tiempo.",correct:!1},{text:"Al desfase horario que sufren por estudiar durante las noches.",correct:!1}]},{id:19,text:"Para mejorar la autoeficacia de un alumno, el profesor debe enseñarle a establecer objetivos que sean:",sorted:!1,options:[{text:"Vagos y generales para evitar la sensación de fracaso si no se cumplen.",correct:!1},{text:"Específicos, próximos en el tiempo y desafiantes.",correct:!0},{text:"Extremadamente fáciles para asegurar el éxito constante sin esfuerzo.",correct:!1},{text:"Únicamente a largo plazo para fomentar la visión de futuro del estudiante.",correct:!1}]},{id:20,text:'Dentro de las adaptaciones metodológicas para TDAH, ¿qué significa "fragmentar los deberes"?',sorted:!1,options:[{text:"Permitir que el alumno no entregue la mitad de las tareas propuestas.",correct:!1},{text:"Dividir una tarea larga en pasos pequeños para facilitar el mantenimiento de la atención.",correct:!0},{text:"Pedir a diferentes alumnos que hagan una parte del trabajo de forma cooperativa.",correct:!1},{text:"Romper físicamente las fichas de trabajo para que parezcan menos cantidad.",correct:!1}]},{id:21,text:"¿Cuál es una recomendación clave para el profesorado ante un alumno con riesgo de conducta suicida?",sorted:!1,options:[{text:"Desdramatizar sus comentarios para no darle importancia y que se le pase la idea.",correct:!1},{text:"Mostrarse cercano, apoyar y no quitar importancia a las ideas de malestar profundo expresadas.",correct:!0},{text:"Mantener una distancia profesional estricta para no involucrarse emocionalmente.",correct:!1},{text:"Prometerle al alumno que guardará el secreto absoluto de sus intenciones.",correct:!1}]},{id:22,text:"En el caso de las Altas Capacidades, ¿por qué es necesaria la enseñanza individualizada o avanzada?",sorted:!1,options:[{text:"Para que el alumno pueda graduarse varios años antes que sus compañeros de edad.",correct:!1},{text:"Porque necesitan un ambiente dinámico y estimulante que evite el aburrimiento y el desinterés.",correct:!0},{text:"Para demostrar al resto de la clase la superioridad intelectual de ciertos individuos.",correct:!1},{text:"Para eximir al profesor de tener que explicarles los contenidos básicos del curso.",correct:!1}]},{id:23,text:"¿Qué herramienta es útil para ayudar a alumnos con TEA a anticipar cambios en la rutina?",sorted:!1,options:[{text:"El uso de alarmas sonoras de alta intensidad.",correct:!1},{text:"El empleo de pictogramas o soportes visuales.",correct:!0},{text:"Explicaciones orales largas y detalladas durante el recreo.",correct:!1},{text:"Dejar que el alumno descubra los cambios por sí mismo para fomentar su autonomía.",correct:!1}]},{id:24,text:"Respecto a la actitud desafiante hacia el profesor, ¿qué acción es desaconsejada?",sorted:!1,options:[{text:"Tratar la situación en privado con el alumno posteriormente.",correct:!1},{text:"Entrar en una lucha de poder directa y pública para reafirmar la autoridad.",correct:!0},{text:"Posponer la resolución del conflicto unos minutos para enfriar la situación.",correct:!1},{text:"Explicar claramente las consecuencias y sanciones de la conducta una vez recuperada la calma.",correct:!1}]},{id:25,text:"En el marco de la diversidad, ¿qué papel juega el departamento de orientación?",sorted:!1,options:[{text:"Es el único responsable de la educación de los alumnos con trastornos, liberando al profesor de aula.",correct:!1},{text:"Actúa de forma coordinada con el profesorado y especialistas externos para sinergizar esfuerzos.",correct:!0},{text:"Se encarga exclusivamente de la sanción y castigo de las conductas disruptivas.",correct:!1},{text:"Su función es solo administrativa, para rellenar los expedientes de becas.",correct:!1}]},{id:26,text:"¿Cuál es la principal finalidad de desarrollar intervenciones educativas adaptadas a las diferencias individuales?",sorted:!1,options:[{text:"Facilitar que todos los alumnos obtengan la misma nota final en los exámenes.",correct:!1},{text:"Desarrollar los conocimientos y competencias necesarias para dominar el aprendizaje.",correct:!0},{text:"Reducir el nivel de exigencia general del centro educativo.",correct:!1},{text:"Cumplir meramente con los trámites burocráticos exigidos por la LOMLOE.",correct:!1}]}],t=[{id:1,text:"¿Cuál es la secuencia ideal que propone el modelo de Honey y Mumford (1986) para que el aprendizaje se considere completo?",sorted:!1,options:[{text:"Abrirse al aprendizaje, reflexionar, elaborar hipótesis y aplicar las conclusiones.",correct:!0},{text:"Analizar datos, aplicar teorías, actuar por impulso y observar resultados.",correct:!1},{text:"Escuchar instrucciones, memorizar conceptos, realizar exámenes y recibir feedback.",correct:!1},{text:"Experimentar, descartar teorías, observar a otros y actuar de nuevo.",correct:!1}]},{id:2,text:"Según García Cué (2006), ¿cómo se definen los estilos de aprendizaje en el contexto educativo?",sorted:!1,options:[{text:"Rasgos cognitivos, afectivos y fisiológicos que sirven como indicadores de cómo las personas perciben y responden a sus ambientes.",correct:!0},{text:"La aptitud innata o talento específico para el cual un aprendiz se encuentra mejor preconfigurado biológicamente.",correct:!1},{text:"Estrategias temporales y cambiantes que el alumno elige según la dificultad de la materia a estudiar.",correct:!1},{text:"Capacidad exclusiva de memorizar y manejar información nueva de forma secuencial y lógica.",correct:!1}]},{id:3,text:"En el modelo VAK de Bandler y Grinder, ¿cuál es una característica distintiva del procesamiento de un alumno visual?",sorted:!1,options:[{text:"Suelen hablar y escribir rápidamente debido a que perciben múltiples imágenes simultáneamente.",correct:!0},{text:"Necesitan feedback oral constante y procesan la información de manera estrictamente lineal.",correct:!1},{text:"Priorizan las sensaciones táctiles y viscerales para validar la información recibida.",correct:!1},{text:"Prefieren el silencio absoluto para poder concentrarse en una sola tarea a la vez.",correct:!1}]},{id:4,text:"¿Qué factor dificulta específicamente el aprendizaje de un estudiante con un estilo predominantemente Teórico?",sorted:!1,options:[{text:"Participar en actividades que enfaticen las emociones, los sentimientos o la ambigüedad.",correct:!0},{text:"Tener que analizar e interpretar grandes cantidades de datos complejos.",correct:!1},{text:"Realizar preguntas constantes sobre la finalidad y los objetivos del programa.",correct:!1},{text:"Adoptar una postura de observador distante antes de participar en una tarea.",correct:!1}]},{id:5,text:"¿Qué representa el uso consciente de diferentes estilos de enseñanza por parte del docente?",sorted:!1,options:[{text:"Un signo de madurez, experiencia y buena práctica docente.",correct:!0},{text:"Una falta de coherencia personal y de identidad profesional definida.",correct:!1},{text:"Un requisito legal obligatorio en todas las programaciones didácticas de secundaria.",correct:!1},{text:"Una estrategia para evitar que los alumnos se aburran con el mismo profesor.",correct:!1}]},{id:6,text:"¿Cuál es la principal preocupación de un alumno con estilo Pragmático al enfrentarse a una nueva situación de aprendizaje?",sorted:!1,options:[{text:"¿Habrá posibilidades de practicar y abordar problemas reales?",correct:!0},{text:"¿Serán sólidos y valiosos los fundamentos teóricos que se van a utilizar?",correct:!1},{text:"¿Tendré tiempo suficiente para asimilar y preparar la información?",correct:!1},{text:"¿Se aceptará que cometa errores y me divierta durante el proceso?",correct:!1}]},{id:7,text:"¿Quién es señalado como el principal responsable del clima de aprendizaje en el aula?",sorted:!1,options:[{text:"El profesor.",correct:!0},{text:"El alumnado adolescente.",correct:!1},{text:"La dirección del centro educativo.",correct:!1},{text:"El entorno familiar y social.",correct:!1}]},{id:8,text:"Según el modelo VAK, ¿qué sensaciones se integran dentro del sistema representacional Kinestésico?",sorted:!1,options:[{text:"Emociones mezcladas con sensaciones táctiles, gustativas, olfativas y viscerales.",correct:!0},{text:"Percepciones visuales de larga distancia y análisis de patrones cromáticos.",correct:!1},{text:"Identificación de tonos, ritmos y secuencias sonoras complejas.",correct:!1},{text:"Representaciones abstractas de conceptos lógicos sin base sensorial física.",correct:!1}]},{id:9,text:"Para un alumno de estilo Reflexivo, ¿cuál de las siguientes situaciones resultaría más difícil para su aprendizaje?",sorted:!1,options:[{text:"Ser forzado a convertirse en el centro de atención o actuar de forma improvisada.",correct:!0},{text:"Tener que escuchar los puntos de vista de otras personas con opiniones diferentes.",correct:!1},{text:"Adoptar la postura de un observador que analiza una situación compleja.",correct:!1},{text:"Disponer de tiempo suficiente para planificar y reunir información pertinente.",correct:!1}]},{id:10,text:"Según Martínez-Geijo (2007), los estilos de enseñanza se fundamentan en actitudes personales que son:",sorted:!1,options:[{text:"Inherentes al docente y abstraídas de su experiencia académica y profesional.",correct:!0},{text:"Imitaciones directas de los modelos pedagógicos de sus propios profesores de primaria.",correct:!1},{text:"Dependientes exclusivamente de los contextos socioeconómicos en los que se encuentra el aula.",correct:!1},{text:"Decisiones arbitrarias tomadas al inicio de cada unidad didáctica.",correct:!1}]},{id:11,text:"En el modelo de Honey y Mumford, ¿cuál es el rasgo definitorio del estilo Activo?",sorted:!1,options:[{text:"Mente abierta y entusiasmo por nuevas tareas, siendo eficientes en el trabajo grupal.",correct:!0},{text:"Prudencia y detallismo, analizando todas las alternativas antes de concluir.",correct:!1},{text:"Perfeccionismo y búsqueda de modelos lógicos al razonar.",correct:!1},{text:"Búsqueda de aplicaciones directas y resolución inmediata de problemas reales.",correct:!1}]},{id:12,text:'¿Por qué es importante para un docente intentar potenciar los estilos de aprendizaje "menos preferentes" en su alumnado?',sorted:!1,options:[{text:"Porque esto capacita al alumno para aprender con eficacia en cualquier situación.",correct:!0},{text:"Porque es la única forma de garantizar que el alumno apruebe los exámenes teóricos.",correct:!1},{text:"Porque los estilos dominantes suelen desaparecer si no se refuerzan constantemente.",correct:!1},{text:"Porque así el profesor no tiene que adaptar su propio estilo de enseñanza.",correct:!1}]},{id:13,text:"En el sistema auditivo de representación sensorial, ¿cómo suele ser el habla de los estudiantes?",sorted:!1,options:[{text:"Más lenta que la de los visuales, eligiendo las palabras con precisión.",correct:!0},{text:"Extremadamente rápida para no perder el hilo de las imágenes mentales.",correct:!1},{text:"Casi inexistente, prefiriendo la comunicación mediante gestos y contacto físico.",correct:!1},{text:"Monótona y sin pausas, ignorando el feedback del interlocutor.",correct:!1}]},{id:14,text:"¿qué relación existe entre los estilos de aprendizaje y la inteligencia?",sorted:!1,options:[{text:"Son independientes; el estilo no está condicionado por el nivel de inteligencia del alumno.",correct:!0},{text:"Existe una correlación directa: a mayor inteligencia, mayor desarrollo del estilo teórico.",correct:!1},{text:"Los alumnos con menor inteligencia solo pueden aprender mediante el estilo activo.",correct:!1},{text:"El estilo kinestésico es el único que requiere una inteligencia emocional superior.",correct:!1}]},{id:15,text:"¿Cuál de los siguientes elementos NO es uno de los componentes que el docente configura en función de su estilo de enseñanza?",sorted:!1,options:[{text:"La predisposición genética del alumnado hacia la materia.",correct:!0},{text:"La metodología didáctica, como el Aprendizaje Cooperativo o el Flipped Learning.",correct:!1},{text:"El método de evaluación utilizado para conocer el progreso del alumno.",correct:!1},{text:"La interacción y el clima afectivo que mantiene con los estudiantes.",correct:!1}]},{id:16,text:"Un alumno que piensa de acuerdo con lo que siente y necesita participar con opiniones y acciones suele pertenecer al sistema sensorial:",sorted:!1,options:[{text:"Kinestésico.",correct:!0},{text:"Auditivo.",correct:!1},{text:"Visual.",correct:!1},{text:"Abstracto.",correct:!1}]},{id:17,text:"¿Qué demostraron autores como Carbo (1982) o Krimsky (1982) respecto a la enseñanza en secundaria?",sorted:!1,options:[{text:"Los estudiantes aprenden más eficazmente cuando se les enseña según sus estilos de aprendizaje predominantes.",correct:!0},{text:"La inteligencia es el único factor determinante del éxito académico en adolescentes.",correct:!1},{text:"Los estilos de aprendizaje cambian radicalmente cada año durante la adolescencia.",correct:!1},{text:"El estilo auditivo es el único eficaz para la enseñanza de idiomas extranjeros.",correct:!1}]},{id:18,text:"Para un aprendiz Activo, una situación de aprendizaje óptima es aquella donde:",sorted:!1,options:[{text:"Se presentan desafíos constantes, drama o crisis emocionales.",correct:!0},{text:"Tiene que trabajar solo en una investigación bibliográfica exhaustiva.",correct:!1},{text:"Se le obliga a asimilar y analizar grandes volúmenes de datos estadísticos.",correct:!1},{text:"La actividad es larga y el resultado solo se verá al final del curso.",correct:!1}]},{id:19,text:"¿cómo afecta el clima del aula a la motivación intrínseca del alumnado?",sorted:!1,options:[{text:"Un clima positivo manejado por el profesor es determinante para no menoscabar esta motivación.",correct:!0},{text:"La motivación intrínseca depende únicamente de la genética del alumno y el clima no influye.",correct:!1},{text:"Solo los premios externos (motivación extrínseca) dependen del clima creado por el profesor.",correct:!1},{text:"El clima del aula solo es relevante en primaria, perdiendo importancia en la adolescencia.",correct:!1}]},{id:20,text:"En el modelo VAK, ¿qué necesidad pedagógica es crítica para un alumno Auditivo?",sorted:!1,options:[{text:"Recibir instrucciones verbales claras y tener la oportunidad de dialogar sobre lo aprendido.",correct:!0},{text:"Observar gráficos de colores vivos y mapas mentales complejos.",correct:!1},{text:"Moverse por el aula y manipular objetos físicos durante la explicación.",correct:!1},{text:"Leer textos en silencio sin ningún tipo de interacción sonora.",correct:!1}]},{id:21,text:"¿Qué situación dificulta el aprendizaje del estilo Pragmático?",sorted:!1,options:[{text:"Realizar actividades que no tienen una finalidad aparente o relación con la realidad.",correct:!0},{text:"Tener que experimentar con ideas novedosas de forma directa.",correct:!1},{text:"Observar a otras personas realizando una tarea antes de intentarla.",correct:!1},{text:"Recibir indicaciones concretas y pautas de acción claras.",correct:!1}]},{id:22,text:'El término "preconfigurado" usado por Reinert (1976) se refiere a:',sorted:!1,options:[{text:"La disposición o talento natural de un aprendiz para recibir y manejar la información de una forma específica.",correct:!0},{text:"El conjunto de conocimientos previos que el alumno trae de cursos anteriores.",correct:!1},{text:"La configuración técnica de los ordenadores que el alumno usa en casa.",correct:!1},{text:"Un estado mental temporal provocado por la motivación del momento.",correct:!1}]},{id:23,text:"¿Qué caracteriza el pensamiento del estilo Teórico según el modelo de Honey y Mumford?",sorted:!1,options:[{text:"Integración de hechos coherentes en teorías lógicas y análisis sintético de la información.",correct:!0},{text:"Generación espontánea de ideas divertidas y arriesgadas sin estructura previa.",correct:!1},{text:"Enfoque exclusivo en el aspecto positivo de las ideas para actuar rápido.",correct:!1},{text:"Observación prudente desde múltiples perspectivas sin llegar a conclusiones.",correct:!1}]},{id:24,text:"¿En qué etapa del desarrollo se encuentra el alumnado que empieza a desarrollar autonomía y decisión sobre su futuro profesional?",sorted:!1,options:[{text:"Adolescencia.",correct:!0},{text:"Infancia temprana.",correct:!1},{text:"Edad adulta madura.",correct:!1},{text:"Vejez.",correct:!1}]},{id:25,text:'¿Cuál es una de las funciones del profesor como "responsable del clima de aprendizaje"?',sorted:!1,options:[{text:"Transmitir su entusiasmo por la materia al alumnado.",correct:!0},{text:"Garantizar que todos los alumnos tengan el mismo estilo de aprendizaje.",correct:!1},{text:"Sustituir la motivación intrínseca del alumno por premios constantes.",correct:!1},{text:"Controlar rígidamente cada movimiento físico de los estudiantes.",correct:!1}]},{id:26,text:'¿Qué se entiende por "ciclo de aprendizaje"?',sorted:!1,options:[{text:"La necesidad de pasar por las cuatro facetas (abierto, reflexionar, elaborar, aplicar) para un aprendizaje pleno.",correct:!0},{text:"El tiempo que transcurre desde que se explica un tema hasta que se realiza el examen final.",correct:!1},{text:"La repetición memorística de un concepto hasta que se graba en la memoria a largo plazo.",correct:!1},{text:"El paso constante de alumnos de un estilo visual a uno auditivo según la materia.",correct:!1}]}],o=[{id:1,text:"¿Cuál es la distinción fundamental entre la inteligencia analítica y la inteligencia creativa dentro de la Teoría Triárquica de Sternberg?",sorted:!1,options:[{text:"La analítica se centra en los componentes internos del procesamiento, mientras que la creativa se ocupa de la habilidad para enfrentar la novedad.",correct:!0},{text:"La analítica busca la adaptación al entorno físico, mientras que la creativa se orienta exclusivamente al pensamiento abstracto y lógico.",correct:!1},{text:"La analítica depende del aprendizaje por observación, mientras que la creativa depende del aprendizaje por reforzamiento.",correct:!1},{text:"La analítica es una capacidad innata que no varía con la edad, mientras que la creativa es un hábito que se adquiere en la adolescencia.",correct:!1}]},{id:2,text:'En el contexto de las Inteligencias Múltiples de Gardner, ¿qué implica la estrategia de "tender puentes"?',sorted:!1,options:[{text:"Utilizar las inteligencias más desarrolladas del alumno para potenciar y facilitar el acceso a aquellas áreas donde presenta mayor debilidad.",correct:!0},{text:"Fomentar la colaboración exclusiva entre alumnos que poseen el mismo perfil de inteligencia predominante.",correct:!1},{text:"Sustituir permanentemente los contenidos de una inteligencia débil por los de una inteligencia fuerte para evitar la frustración.",correct:!1},{text:"Priorizar el desarrollo de las inteligencias lingüística y lógica por encima de las artísticas para asegurar el éxito laboral.",correct:!1}]},{id:3,text:"Según la teoría de Piaget, ¿cuál es la característica funcional más importante del pensamiento formal que permite derivar todas las demás?",sorted:!1,options:[{text:"La subordinación de lo real a lo posible.",correct:!0},{text:"El predominio del pensamiento concreto sobre el abstracto.",correct:!1},{text:"La capacidad de realizar operaciones aritméticas básicas sin apoyo visual.",correct:!1},{text:"La limitación del razonamiento a objetos físicamente presentes.",correct:!1}]},{id:4,text:'Dentro del pensamiento crítico, ¿cómo se define el "coraje intelectual" según Paul y Langer?',sorted:!1,options:[{text:"La capacidad de afrontar ideas o decisiones a pesar de que generen una carga emocional negativa o rechazo inicial.",correct:!0},{text:"La habilidad de imponer el propio criterio sobre el grupo cuando se tiene la certeza de poseer la verdad.",correct:!1},{text:"El instinto de defender las creencias tradicionales frente a cualquier nueva evidencia científica.",correct:!1},{text:"La velocidad para resolver problemas matemáticos complejos bajo presión de tiempo.",correct:!1}]},{id:5,text:'En el proceso creativo propuesto por Csikszentmihalyi, ¿qué ocurre específicamente durante la fase de "incubación"?',sorted:!1,options:[{text:"El procesamiento inconsciente de la información y la generación de asociaciones entre ideas, a menudo acompañadas de duda.",correct:!0},{text:"La recopilación sistemática de datos y la inmersión consciente en el problema de interés.",correct:!1},{text:'El momento repentino en que el sujeto se da cuenta de la solución o "insight".',correct:!1},{text:"La evaluación final de la idea para determinar si es útil o si debe ser rechazada por el entorno.",correct:!1}]},{id:6,text:"¿Por qué se afirma que la Inteligencia Emocional (IE) es un factor determinante en el rendimiento académico de secundaria?",sorted:!1,options:[{text:"Porque facilita la motivación intrínseca, el trabajo en equipo y el equilibrio psicológico necesario para el aprendizaje.",correct:!0},{text:"Porque sustituye la necesidad de poseer capacidades cognitivas lógicas o memorísticas superiores.",correct:!1},{text:"Porque permite al alumno memorizar contenidos con mayor velocidad mediante el uso de la amígdala.",correct:!1},{text:"Porque garantiza que el alumno nunca cometa errores en las tareas de resolución de problemas.",correct:!1}]},{id:7,text:'¿Qué diferencia al "pensador efectivo" del "pensador natural" según Martín-Lobo?',sorted:!1,options:[{text:"El pensador efectivo desarrolla su pensamiento de manera consciente, planificando y reflexionando sistemáticamente sobre sus habilidades.",correct:!0},{text:"El pensador efectivo posee un Cociente Intelectual (CI) hereditario significativamente más alto.",correct:!1},{text:"El pensador natural solo utiliza el pensamiento abstracto, mientras que el efectivo utiliza el concreto.",correct:!1},{text:"El pensador natural depende de la mediación social, mientras que el efectivo es totalmente autodidacta.",correct:!1}]},{id:8,text:'En el marco de la teoría de Piaget sobre el pensamiento formal, ¿qué significa que este tenga un "carácter proposicional"?',sorted:!1,options:[{text:"Que el razonamiento se basa en enunciados verbales que contienen datos, no necesariamente en objetos reales presentes.",correct:!0},{text:"Que el alumno solo puede pensar si tiene una propuesta de recompensa externa inmediata.",correct:!1},{text:"Que el pensamiento está limitado a la clasificación de objetos físicos en categorías simples.",correct:!1},{text:"Que el adolescente siempre acepta las propuestas del profesor sin realizar crítica alguna.",correct:!1}]},{id:9,text:'Según el enfoque constructivista (Piaget, Vigotsky), ¿cuál es el papel de los "conflictos cognitivos" en el aula?',sorted:!1,options:[{text:"Actuar como catalizadores que obligan al alumno a reestructurar sus esquemas previos para alcanzar un nuevo equilibrio.",correct:!0},{text:"Ser evitados a toda costa para prevenir el estrés y asegurar un clima de aprendizaje pasivo.",correct:!1},{text:"Demostrar que el profesor posee la única respuesta válida ante un problema complejo.",correct:!1},{text:"Reducir la inteligencia emocional del grupo al generar discusiones personales.",correct:!1}]},{id:10,text:'Gardner describe el sistema educativo tradicional como "half-brained". ¿A qué se refiere con este término?',sorted:!1,options:[{text:"A que se priorizan casi exclusivamente las inteligencias lingüística y lógico-matemática, ignorando otras potencialidades mentales.",correct:!0},{text:"A que los adolescentes solo tienen desarrollado el hemisferio derecho del cerebro.",correct:!1},{text:"A que la mitad de los alumnos no poseen capacidades creativas por razones genéticas.",correct:!1},{text:"A que el aprendizaje emocional ocurre en una parte del cerebro desconectada del razonamiento.",correct:!1}]},{id:11,text:"¿Cuál es una de las evidencias que utiliza Gardner para justificar la autonomía de cada inteligencia?",sorted:!1,options:[{text:"La existencia de lesiones cerebrales que anulan una capacidad específica dejando intactas las demás.",correct:!0},{text:"El hecho de que todos los seres humanos puntúan igual en todas las dimensiones de los test de CI.",correct:!1},{text:"La imposibilidad de codificar la música o la danza mediante sistemas de símbolos.",correct:!1},{text:"Que la inteligencia es una estructura unitaria y estable que no cambia con la cultura.",correct:!1}]},{id:12,text:"En la Teoría Triárquica de Sternberg, ¿qué caracteriza a la inteligencia práctica o contextual?",sorted:!1,options:[{text:"La habilidad para aplicar y utilizar conocimientos en situaciones reales y adaptarse al entorno.",correct:!0},{text:"La capacidad de realizar análisis literarios profundos y comparaciones abstractas.",correct:!1},{text:"El dominio de procesos metacognitivos para automatizar tareas repetitivas.",correct:!1},{text:"La predisposición genética a resolver acertijos lógico-matemáticos en test psicométricos.",correct:!1}]},{id:13,text:'¿Cómo define Vigotsky la "Zona de Desarrollo Próximo" (ZDP)?',sorted:!1,options:[{text:"La distancia entre lo que el alumno puede hacer solo y lo que puede lograr con la ayuda de un mediador más capacitado.",correct:!0},{text:"El período crítico de la pubertad donde los cambios biológicos impiden el aprendizaje formal.",correct:!1},{text:"El área del cerebro encargada de procesar las emociones durante la adolescencia.",correct:!1},{text:"El espacio físico del aula que debe estar libre de distracciones para fomentar la creatividad.",correct:!1}]},{id:14,text:"Para potenciar la creatividad en el aula, ¿cuál de estos factores se refiere a la capacidad de cambiar el enfoque o producir ideas diferentes?",sorted:!1,options:[{text:"Flexibilidad.",correct:!0},{text:"Fluidez.",correct:!1},{text:"Sensibilidad.",correct:!1},{text:"Elaboración.",correct:!1}]},{id:15,text:'¿Qué implicación tiene la "naturaleza combinatoria" del pensamiento formal en la resolución de problemas?',sorted:!1,options:[{text:"Que los adolescentes pueden considerar sistemáticamente todas las combinaciones posibles de variables para hallar una solución.",correct:!0},{text:"Que el alumno mezcla recuerdos emocionales con datos científicos de forma desorganizada.",correct:!1},{text:"Que la inteligencia es el resultado de combinar la herencia genética al 50% con el ambiente.",correct:!1},{text:"Que solo se pueden resolver problemas si se trabaja en parejas (combinando personas).",correct:!1}]},{id:16,text:"¿Qué efecto pueden tener los problemas emocionales graves (como el maltrato) en el desarrollo cognitivo?",sorted:!1,options:[{text:"Pueden interferir significativamente en la capacidad de pensamiento formal, la concentración y la motivación.",correct:!0},{text:"Aceleran el paso al pensamiento abstracto como mecanismo de defensa psicológica.",correct:!1},{text:"No tienen ninguna influencia, ya que la inteligencia es una estructura biológica independiente de las vivencias.",correct:!1},{text:"Solo afectan a la inteligencia emocional, manteniendo intacta la inteligencia lógico-matemática.",correct:!1}]},{id:17,text:'Dentro de la inteligencia emocional, ¿a qué se refiere el término "adaptación social"?',sorted:!1,options:[{text:"A la calidad de las relaciones sociales, la empatía y la conducta prosocial que favorece el funcionamiento en el medio.",correct:!0},{text:"A la capacidad de imitar los movimientos físicos de los compañeros en clase de educación física.",correct:!1},{text:"Al proceso de seguir las normas escolares únicamente por miedo al castigo externo.",correct:!1},{text:"A la habilidad de ocultar cualquier sentimiento para parecer una persona racional ante los profesores.",correct:!1}]},{id:18,text:'¿Qué recomienda Sternberg para educar en una "inteligencia exitosa"?',sorted:!1,options:[{text:"Enseñar y evaluar equilibradamente las tres inteligencias: analítica, práctica y creativa.",correct:!0},{text:"Centrarse únicamente en la inteligencia analítica para asegurar una alta puntuación en el Cociente Intelectual.",correct:!1},{text:"Eliminar los exámenes de teoría y basar toda la educación en la inteligencia práctica.",correct:!1},{text:"Fomentar solo la inteligencia creativa, ya que el resto de procesos se automatizarán solos con la edad.",correct:!1}]},{id:19,text:'En el desarrollo cognitivo adolescente, ¿qué implica poseer "metacognición"?',sorted:!1,options:[{text:"Ser consciente de los propios procesos de pensamiento y ser capaz de autorregular el aprendizaje.",correct:!0},{text:"Tener la capacidad de memorizar grandes volúmenes de datos sin comprender su significado.",correct:!1},{text:"Creer que la propia opinión es la única posible sobre un tema (egocentrismo intelectual).",correct:!1},{text:"Depender exclusivamente de las instrucciones del profesor para realizar cualquier tarea mínima.",correct:!1}]},{id:20,text:'Según el modelo de inteligencia de Gardner, ¿en qué consiste la "inteligencia existencial"?',sorted:!1,options:[{text:"En la captación y reflexión sobre cuestiones fundamentales de la existencia humana.",correct:!0},{text:"En la habilidad para sobrevivir en entornos naturales peligrosos sin herramientas modernas.",correct:!1},{text:"En la capacidad de determinar con precisión el estado de humor de los demás.",correct:!1},{text:"En el dominio de los movimientos corporales para actividades deportivas de alto riesgo.",correct:!1}]},{id:21,text:"¿Cuál es un factor determinante para que el profesor potencie la creatividad?",sorted:!1,options:[{text:"Ser él mismo un modelo de creatividad y no estructurar en exceso el planteamiento de problemas.",correct:!0},{text:"Proporcionar siempre la solución correcta al inicio de la clase para ahorrar tiempo de incubación.",correct:!1},{text:"Penalizar severamente los errores para fomentar la búsqueda de la idea perfecta desde el principio.",correct:!1},{text:"Asegurar que todas las actividades del aula sean individuales y competitivas.",correct:!1}]},{id:22,text:'En el pensamiento crítico, la "actuación justa" implica:',sorted:!1,options:[{text:"Adherirse a normas intelectuales independientemente de los propios sentimientos o intereses personales.",correct:!0},{text:"Premiar solo a los alumnos que están de acuerdo con la ideología del docente.",correct:!1},{text:"Realizar juicios rápidos basados en la intuición emocional para ganar agilidad.",correct:!1},{text:"Ignorar la información que contradice nuestras creencias para mantener la coherencia interna.",correct:!1}]},{id:23,text:"¿Qué relación establece Gardner entre las inteligencias múltiples y la creatividad?",sorted:!1,options:[{text:"Propone que existen tantas creatividades como inteligencias, cada una con su propia red de relaciones.",correct:!0},{text:"Sostiene que la creatividad es una inteligencia única que domina a las otras ocho.",correct:!1},{text:"Afirma que solo las inteligencias artísticas (musical y cinética) pueden ser creativas.",correct:!1},{text:"Indica que la creatividad desaparece al desarrollar el pensamiento lógico-matemático formal.",correct:!1}]},{id:24,text:'¿Por qué es importante enseñar "modelos de toma de decisiones" en secundaria?',sorted:!1,options:[{text:"Para que comprendan que toda decisión conlleva un riesgo de error y aprendan a buscar información para reducirlo.",correct:!0},{text:"Para asegurar que los alumnos elijan siempre las carreras universitarias con más salidas laborales.",correct:!1},{text:"Porque los adolescentes aún no son capaces de considerar consecuencias a largo plazo debido a su cerebro.",correct:!1},{text:"Para evitar que los alumnos tengan que decidir por sí mismos y sigan solo el criterio paterno.",correct:!1}]},{id:25,text:'¿Cuál es la función del "proceso de internalización" en la teoría de Vigotsky?',sorted:!1,options:[{text:"Construir individualmente esquemas de conocimiento a partir de la base social y cultural previamente socializada.",correct:!0},{text:"Memorizar las normas del centro sin cuestionarlas para evitar conflictos con el profesorado.",correct:!1},{text:"Rechazar cualquier influencia externa para desarrollar una inteligencia puramente genética.",correct:!1},{text:"Repetir mecánicamente las palabras del profesor durante un examen.",correct:!1}]},{id:26,text:"En el marco del pensamiento crítico de Langer, ¿qué aspecto debe priorizar el profesor sobre los resultados del aprendizaje?",sorted:!1,options:[{text:"El proceso de pensamiento y la atención reflexiva a la información.",correct:!0},{text:"La calificación numérica obtenida en pruebas estandarizadas de respuesta corta.",correct:!1},{text:"La velocidad con la que el alumno entrega sus tareas terminadas.",correct:!1},{text:"La ausencia total de dudas o preguntas por parte del alumnado durante la explicación.",correct:!1}]}];export{e as ADP_UD1_QUESTIONS,a as ADP_UD2_QUESTIONS,t as ADP_UD3_QUESTIONS,o as ADP_UD4_QUESTIONS};